Script.Workflow:
module Win11ButtonColors;
using presentation::*;
using presentation::controls::*;
namespace win11skin
{
  struct ButtonColors
  {
    Border : Color;
    Face : Color;
    Text : Color;
    Bullet : Color;
    HideBackground : bool;
    HideBorder : bool;
  }

  class ButtonColorState
  {
    prop Border : Color = {} {}
    prop Face : Color = {} {}
    prop Text : Color = {} {}
    prop Bullet : Color = {} {}
    prop BackgroundProgress : double = 1.0 {}
    prop BorderProgress : double = 1.0 {}

    new() {}

    new(colors : ButtonColors)
    {
      Border = colors.Border;
      Face = colors.Face;
      Text = colors.Text;
      Bullet = colors.Bullet;
      BackgroundProgress = colors.HideBackground ? 0.0 : 1.0;
      BorderProgress = colors.HideBackground or colors.HideBorder ? 0.0 : 1.0;
    }
  }

  func CompleteColorAnimation(animation : IGuiAnimation^, completed : func():void) : IGuiAnimation^
  ${
    $PlayAndWait animation;
    completed();
  }

  func GetButtonColors(enabled : bool, state : ButtonState) : ButtonColors
  {
    return not enabled ? win11Colors.ButtonDisabled :
      state == ButtonState::Pressed ? win11Colors.ButtonPressed :
      state == ButtonState::Active ? win11Colors.ButtonHovered : win11Colors.ButtonNormal;
  }

  func GetCheckedColors(enabled : bool, state : ButtonState, selected : bool) : ButtonColors
  {
    if (selected)
    {
      return not enabled ? win11Colors.CheckedDisabled :
        state == ButtonState::Pressed ? win11Colors.CheckedPressed :
        state == ButtonState::Active ? win11Colors.CheckedHovered : win11Colors.CheckedNormal;
    }
    return not enabled ? win11Colors.MarkDisabled :
      state == ButtonState::Pressed ? win11Colors.MarkPressed :
      state == ButtonState::Active ? win11Colors.MarkHovered : win11Colors.MarkNormal;
  }

  func GetRibbonCommandColors(enabled : bool, state : ButtonState, selected : bool) : ButtonColors
  {
    if (selected)
    {
      var colors = GetCheckedColors(enabled, state, true);
      return {Border:colors.Border; Face:colors.Face; Text:colors.Bullet; Bullet:colors.Bullet;};
    }
    return not enabled ? win11Colors.SubtleDisabled :
      state == ButtonState::Pressed ? win11Colors.SubtlePressed :
      state == ButtonState::Active ? win11Colors.SubtleHovered : win11Colors.SubtleNormal;
  }

  func GetScrollButtonColors(enabled : bool, state : ButtonState, arrow : bool) : ButtonColors
  {
    if (arrow)
    {
      return not enabled ? win11Colors.SubtleDisabled :
        state == ButtonState::Pressed ? win11Colors.SubtlePressed :
        state == ButtonState::Active ? win11Colors.SubtleHovered : win11Colors.SubtleNormal;
    }
    return not enabled ? win11Colors.SubtleDisabled :
      state == ButtonState::Pressed ? win11Colors.ThumbPressed :
      state == ButtonState::Active ? win11Colors.ThumbHovered : win11Colors.ThumbNormal;
  }
}

Instance.ref.Members:
var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(win11Colors.ButtonNormal));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetButtonColors(self.VisuallyEnabled, self.State)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}
